// メソッド抽出の前(totalBefore)と後(totalAfter)を比べる
// ここを変えてみよう:inputs に配列を足す / subtotal の中身をわざと壊して「違う!」を出す
static int totalBefore(int[] prices) {
    int sum = 0;
    for (int p : prices) {
        sum += p;
    }
    return sum + sum / 10;
}

static int subtotal(int[] prices) {
    int sum = 0;
    for (int p : prices) {
        sum += p;
    }
    return sum;
}

static int totalAfter(int[] prices) {
    int sum = subtotal(prices);
    return sum + sum / 10;
}

int[][] inputs = {{100, 200}, {}, {999}, {1, 2, 3}};
for (int[] in : inputs) {
    int before = totalBefore(in);
    int after = totalAfter(in);
    System.out.println(java.util.Arrays.toString(in) + " → 前: " + before
            + " / 後: " + after + (before == after ? " 同じ" : " 違う!"));
}

